    provider: 'anthropic',
    input: ['text', 'image'],
    runnable: true,
    authConfigured: true,
    authSource: 'stored',
    authLabel: 'auth.json',
    statusLabel: 'Ready',
  },
  {
    id: 'deepseek-v4-flash:0731-cloud',
    name: 'DeepSeek v4 Flash (Cloud)',
    provider: 'ollama-cloud',
    input: ['text'],
    runnable: true,
    authConfigured: true,
    authSource: 'models_json_key',
    statusLabel: 'Ready',
  },
  {
    id: 'glm-5.3-flash:cloud',
    name: 'GLM 5.3 Flash (Cloud)',
