#!/usr/bin/env node
/***
 * MARK: check-one-function-per-file
 * @description New-file shape gate (WP-8, binding q1/q2/q3/q13): every source
 *   file outside the grandfather allowlist must declare at most ONE top-level
 *   named function. Only `function name` declarations at brace depth 0 count
 *   (nested declarations, callbacks, and arrow-function constants are ignored
 *   per q1). Files that already held >= 2 top-level named functions when the
 *   gate landed are listed in `scripts/allowlists/one-function-per-file.json`
 *   and keep passing untouched (q13); an allowlisted path that is itself
 *   newly added still fails so the list cannot grandfather brand-new code.
 * @example node scripts/check-one-function-per-file.mjs (exit 0 on a clean tree)
 * @example node scripts/check-one-function-per-file.mjs --write-allowlist
 * @example node scripts/check-one-function-per-file.mjs --report
 ***/

import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(HERE, "..");
export const ALLOWLIST_PATH = path.join(
	REPO_ROOT,
	"scripts",
	"allowlists",
	"one-function-per-file.json",
);

const ROOTS = ["api", "shared", path.join("frontend", "src")];
const SOURCE_EXTS = new Set([".js", ".jsx"]);
const SKIP_BASENAMES = new Set(["node_modules", "dist", ".git", "coverage"]);

/***
 * MARK: isSourceFile
 * @description Whether a repo-relative POSIX path is in the gate's scope:
 *   a .js/.jsx file under api/, shared/, or frontend/src/, excluding
 *   test/spec files, node_modules, and build output.
 * @example isSourceFile("api/work/taskErrors.js") => true
 * @param {string} relPath - Repo-relative POSIX path.
 * @returns {boolean} True when the file is checked by this gate.
 ***/
export function isSourceFile(relPath) {
	const ext = path.posix.extname(relPath);
	if (!SOURCE_EXTS.has(ext)) return false;
	if (!ROOTS.some((root) => relPath === root || relPath.startsWith(`${root}/`)))
		return false;
	const base = path.posix.basename(relPath);
	if (base.includes(".test.") || base.includes(".spec.")) return false;
	if (relPath.split("/").some((part) => SKIP_BASENAMES.has(part))) return false;
	return true;
}

/***
 * MARK: stripNonCode
 * @description Masks comments and string/template literals with spaces (keeping
 *   newlines and length stable) so keyword scans never match prose, URLs, or
 *   doc examples. Handles line/block comments, single/double quotes, and
 *   template literals with `${}` interpolation.
 * @example stripNonCode("const s = 'function x';") hides the quoted words
 * @param {string} source - Raw file text.
 * @returns {string} Masked text of identical length.
 ***/
export function stripNonCode(source) {
	const out = source.split("");
	const len = source.length;
	const mask = (from, to) => {
		for (let k = from; k < to; k++) {
			if (out[k] !== "\n") out[k] = " ";
		}
	};
	const skipString = (i) => {
		const quote = source[i];
		let j = i + 1;
		while (j < len) {
			if (source[j] === "\\") j += 2;
			else if (source[j] === quote) {
				j++;
				break;
			} else j++;
		}
		mask(i, j);
		return j;
	};
	// Skips `${ ... }` starting at the `$`, honouring nested strings,
	// comments, templates, and braces. Returns the index after the `}`.
	const skipInterpolation = (i) => {
		let j = i + 2;
		let depth = 1;
		while (j < len && depth > 0) {
			const ch = source[j];
			const next = source[j + 1];
			if (ch === "/" && next === "/") {
				let k = j + 2;
				while (k < len && source[k] !== "\n") k++;
				mask(j, k);
				j = k;
			} else if (ch === "/" && next === "*") {
				const end = source.indexOf("*/", j + 2);
				const k = end === -1 ? len : end + 2;
				mask(j, k);
				j = k;
			} else if (ch === "'" || ch === '"') {
				j = skipString(j);
			} else if (ch === "`") {
				j = skipTemplate(j);
			} else {
				if (ch === "{") depth++;
				else if (ch === "}") depth--;
				j++;
			}
		}
		return j;
	};
	// Masks a template literal starting at the backtick, scanning
	// `${}` interpolations as code. Returns the index after the closing
	// backtick (or end of input for an unterminated literal).
	const skipTemplate = (i) => {
		let j = i + 1;
		let segStart = j;
		while (j < len) {
			const ch = source[j];
			if (ch === "\\") j += 2;
			else if (ch === "`") {
				mask(segStart, j);
				mask(j, j + 1);
				return j + 1;
			} else if (ch === "$" && source[j + 1] === "{") {
				mask(segStart, j);
				j = skipInterpolation(j);
				segStart = j;
			} else j++;
		}
		if (segStart < len) mask(segStart, len);
		return len;
	};
	let i = 0;
	while (i < len) {
		const ch = source[i];
		const next = source[i + 1];
		if (ch === "/" && next === "/") {
			let j = i + 2;
			while (j < len && source[j] !== "\n") j++;
			mask(i, j);
			i = j;
		} else if (ch === "/" && next === "*") {
			const end = source.indexOf("*/", i + 2);
			const j = end === -1 ? len : end + 2;
			mask(i, j);
			i = j;
		} else if (ch === "'" || ch === '"') {
			i = skipString(i);
		} else if (ch === "`") {
			i = skipTemplate(i);
		} else {
			i++;
		}
	}
	return out.join("");
}

/***
 * MARK: topLevelFunctions
 * @description Lists top-level named `function` declarations in a source file:
 *   `function foo`, `async function foo`, `export function foo`,
 *   `export default function foo` (anonymous defaults are ignored — there is
 *   no name to split into its own file). Nested declarations sit at brace
 *   depth > 0 and are ignored per q1, as are arrow-function constants (no
 *   `function` keyword).
 * @example topLevelFunctions("export function a() {}\nfunction b() {}") => ["a", "b"]
 * @param {string} source - Raw file text.
 * @returns {Array<string>} Declared names in source order.
 ***/
export function topLevelFunctions(source) {
	const masked = stripNonCode(source);
	const names = [];
	const len = masked.length;
	let depth = 0;
	const isIdChar = (c) => /[$\w]/.test(c);
	let i = 0;
	while (i < len) {
		const ch = masked[i];
		if (ch === "{" || ch === "}") {
			depth += ch === "{" ? 1 : -1;
			if (depth < 0) depth = 0;
			i++;
			continue;
		}
		if (
			ch === "f" &&
			masked.startsWith("function", i) &&
			!isIdChar(masked[i - 1] || "") &&
			!isIdChar(masked[i + 8] || "")
		) {
			let j = i + 8;
			while (j < len && /\s/.test(masked[j])) j++;
			if (masked[j] === "*") {
				j++;
				while (j < len && /\s/.test(masked[j])) j++;
			}
			let name = "";
			while (j < len && isIdChar(masked[j])) {
				name += masked[j];
				j++;
			}
			if (depth === 0 && name) names.push(name);
			i = j;
			continue;
		}
		i++;
	}
	return names;
}

/***
 * MARK: collectSourceFiles
 * @description Walks the gate's roots and returns every in-scope source file
 *   as a repo-relative POSIX path, sorted.
 * @example collectSourceFiles().every(isSourceFile) => true
 * @returns {Array<string>} Sorted repo-relative POSIX paths.
 ***/
export function collectSourceFiles() {
	const found = [];
	const walk = (dir) => {
		for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
			if (entry.name.startsWith(".") || SKIP_BASENAMES.has(entry.name)) continue;
			const full = path.join(dir, entry.name);
			if (entry.isDirectory()) walk(full);
			else if (entry.isFile()) {
				const rel = path.relative(REPO_ROOT, full).split(path.sep).join("/");
				if (isSourceFile(rel)) found.push(rel);
			}
		}
	};
	for (const root of ROOTS) {
		const abs = path.join(REPO_ROOT, root);
		if (fs.existsSync(abs)) walk(abs);
	}
	return found.sort();
}

/***
 * MARK: readAllowlist
 * @description Reads the committed grandfather allowlist (empty when absent —
 *   a missing file means "no grandfathered files", never a crash).
 * @example readAllowlist() returns an array of repo-relative paths
 * @returns {Array<string>} Sorted allowlisted repo-relative POSIX paths.
 ***/
export function readAllowlist() {
	try {
		const raw = JSON.parse(fs.readFileSync(ALLOWLIST_PATH, "utf8"));
		return Array.isArray(raw) ? [...raw].sort() : [];
	} catch {
		return [];
	}
}

/***
 * MARK: resolveDiffBase
 * @description Resolves the merge-base ancestor for newly-added detection
 *   (origin/master, origin/main, master, main — first that resolves), or null
 *   outside a git checkout / with no known default branch.
 * @example resolveDiffBase() => "abc123..." or null
 * @returns {string|null} A commit-ish, or null when git cannot answer.
 ***/
export function resolveDiffBase() {
	try {
		for (const ref of ["origin/master", "origin/main", "master", "main"]) {
			try {
				execFileSync("git", ["rev-parse", "--verify", ref], {
					cwd: REPO_ROOT,
					stdio: ["ignore", "pipe", "ignore"],
				});
				return ref;
			} catch {
				// Try the next candidate.
			}
		}
		return null;
	} catch {
		return null;
	}
}

/***
 * MARK: listNewlyAdded
 * @description Repo-relative POSIX paths that are newly added: committed as
 *   Added vs the diff base, or untracked (`??`) in the working tree. An
 *   allowlisted path that is newly added still fails — the allowlist is for
 *   files that existed before the gate (q13), not a way to grandfather
 *   brand-new code. Degrades to [] when git is unavailable.
 * @example listNewlyAdded().every((p) => typeof p === "string") => true
 * @returns {Array<string>} Newly-added repo-relative POSIX paths.
 ***/
export function listNewlyAdded() {
	try {
		const added = new Set();
		const base = resolveDiffBase();
		if (base) {
			const out = execFileSync(
				"git",
				["diff", "--name-status", "--diff-filter=A", `${base}...HEAD`],
				{ cwd: REPO_ROOT, encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] },
			);
			for (const line of out.split("\n")) {
				const file = line.replace(/^[AMDRCTUX]+\s+/, "").trim();
				if (file) added.add(file);
			}
		}
		const status = execFileSync("git", ["status", "--porcelain"], {
			cwd: REPO_ROOT,
			encoding: "utf8",
			stdio: ["ignore", "pipe", "ignore"],
		});
		for (const line of status.split("\n")) {
			if (line.startsWith("??")) {
				const file = line.slice(2).trim().replace(/"/g, "");
				if (file) added.add(file.endsWith("/") ? file : file);
			}
		}
		return [...added].sort();
	} catch {
		return [];
	}
}

/***
 * MARK: checkFiles
 * @description Pure gate core: for each file's declared top-level functions,
 *   fails paths with >= 2 names unless allowlisted AND not newly added.
 * @example checkFiles({ "a.js": ["f", "g"] }, [], []) fails a.js
 * @param {Object<string, Array<string>>} counts - File -> declared names.
 * @param {Array<string>} allowlist - Grandfathered paths.
 * @param {Array<string>} newlyAdded - Newly-added paths (still fail).
 * @returns {{ failures: Array<Object>, stale: Array<string> }} Failures and allowlist entries no longer needed.
 ***/
export function checkFiles(counts, allowlist, newlyAdded) {
	const allowed = new Set(allowlist);
	const added = new Set(newlyAdded);
	const failures = [];
	for (const [file, names] of Object.entries(counts)) {
		if (names.length < 2) continue;
		if (allowed.has(file) && !added.has(file)) continue;
		failures.push({ file, names, grandfatheredButNew: allowed.has(file) });
	}
	const stale = allowlist.filter((file) => (counts[file] || []).length < 2);
	return { failures, stale };
}

/***
 * MARK: formatFailure
 * @description Renders the remediation-forward gate failure (plan §4.4/§7:
 *   gate name, offending locations, why, remediation, local repro).
 * @example formatFailure([{ file: "a.js", names: ["f", "g"] }]) mentions one-function-per-file
 * @param {Array<Object>} failures - Failing files with declared names.
 * @returns {string} Human-readable failure text.
 ***/
export function formatFailure(failures) {
	const lines = ["FAIL: new-file shape (one-function-per-file)", ""];
	for (const { file, names, grandfatheredButNew } of failures) {
		lines.push(`${file} — ${names.length} top-level named functions:`);
		names.forEach((name, i) => lines.push(`  ${i + 1}. ${name}`));
		if (grandfatheredButNew) {
			lines.push("  (this path is allowlisted, but it is newly added: the");
			lines.push("  allowlist only covers files that existed before the gate.)");
		}
		lines.push("");
	}
	lines.push("Newly added source files must declare at most one top-level named function.");
	lines.push("");
	lines.push("Remediation:");
	lines.push("  1. Split each function into its own file named after the function");
	lines.push("     (e.g. api/work/buildFoo.js for function buildFoo).");
	lines.push("  2. Keep this file as a barrel re-export if callers need one entry point.");
	lines.push("  3. Do NOT add this file to scripts/allowlists/one-function-per-file.json:");
	lines.push("     that list is reserved for files that existed before this gate (q13).");
	lines.push("See: AGENTS-MAP.md §one-function-per-file, KB Code Standards §modularity.");
	lines.push("");
	lines.push("Reproduce locally: npm run check:one-function");
	return lines.join("\n");
}

function scanCounts() {
	const counts = {};
	for (const file of collectSourceFiles()) {
		const source = fs.readFileSync(path.join(REPO_ROOT, file), "utf8");
		counts[file] = topLevelFunctions(source);
	}
	return counts;
}

const invokedDirectly =
	process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (invokedDirectly) {
	const args = new Set(process.argv.slice(2));
	if (args.has("--write-allowlist")) {
		const counts = scanCounts();
		const listed = Object.entries(counts)
			.filter(([, names]) => names.length >= 2)
			.map(([file]) => file)
			.sort();
		fs.mkdirSync(path.dirname(ALLOWLIST_PATH), { recursive: true });
		fs.writeFileSync(ALLOWLIST_PATH, `${JSON.stringify(listed, null, 2)}\n`);
		console.log(`allowlist: wrote ${listed.length} files to ${path.relative(REPO_ROOT, ALLOWLIST_PATH)}`);
	} else {
		const counts = scanCounts();
		const allowlist = readAllowlist();
		const newlyAdded = listNewlyAdded();
		if (args.has("--report")) {
			const multi = Object.entries(counts).filter(([, names]) => names.length >= 2);
			console.log(`one-function-per-file report: ${multi.length} multi-function files`);
			for (const [file, names] of multi) {
				const tag = allowlist.includes(file) ? "allowlisted" : "UNLISTED";
				console.log(`  ${tag} ${file} (${names.length}): ${names.join(", ")}`);
			}
			const { stale } = checkFiles(counts, allowlist, newlyAdded);
			if (stale.length > 0) {
				console.log(`stale allowlist entries (now <= 1 function, may prune): ${stale.join(", ")}`);
			}
		}
		const { failures } = checkFiles(counts, allowlist, newlyAdded);
		if (failures.length > 0) {
			console.error(formatFailure(failures));
			process.exit(1);
		}
		console.log(
			`one-function-per-file: PASS (${Object.keys(counts).length} files scanned, ${allowlist.length} grandfathered)`,
		);
	}
}

import React from 'react';
import { describe, expect, it, vi } from 'vitest';
import { screen, fireEvent } from '@testing-library/react';
import { renderWithKainBain } from '../../testUtils';
import { SettingsSearchInput } from './SettingsSearchInput';
import '@testing-library/jest-dom';

/***
 * MARK: SettingsSearchInput tests
 * @description Verifies the settings search box: typing shows matches with
 *   tab names, keyboard navigation and Enter select a result, Escape closes
 *   the dropdown, and clicking a result calls onSelect.
 ***/
describe('SettingsSearchInput', () => {
  it('shows matching results with tab names while typing', () => {
    renderWithKainBain(<SettingsSearchInput onSelect={vi.fn()} />);
    fireEvent.change(screen.getByLabelText('Search settings'), {
      target: { value: 'git' },
    });
    expect(screen.getByRole('listbox')).toBeInTheDocument();
    expect(screen.getByText('Git Repository URL')).toBeInTheDocument();
    // Results name their home tab.
    expect(screen.getAllByText('Files & Links').length).toBeGreaterThan(0);
  });

  it('shows no dropdown for a blank query or no matches', () => {
    renderWithKainBain(<SettingsSearchInput onSelect={vi.fn()} />);
    expect(screen.queryByRole('listbox')).not.toBeInTheDocument();
    fireEvent.change(screen.getByLabelText('Search settings'), {
      target: { value: 'zzz-no-such-setting' },
    });
    expect(screen.queryByRole('listbox')).not.toBeInTheDocument();
  });

  it('selects the highlighted result on Enter', () => {
    const onSelect = vi.fn();
    renderWithKainBain(<SettingsSearchInput onSelect={onSelect} />);
    const input = screen.getByLabelText('Search settings');
    fireEvent.change(input, { target: { value: 'git' } });
    // Move past the first result, then jump.
    fireEvent.keyDown(input, { key: 'ArrowDown' });
    fireEvent.keyDown(input, { key: 'Enter' });
    expect(onSelect).toHaveBeenCalledTimes(1);
    expect(onSelect.mock.calls[0][0].tab).toBe('files');
    // Choosing clears the query and closes the dropdown.
    expect(input).toHaveValue('');
    expect(screen.queryByRole('listbox')).not.toBeInTheDocument();
  });

  it('ArrowUp wraps to the last result', () => {
    const onSelect = vi.fn();
    renderWithKainBain(<SettingsSearchInput onSelect={onSelect} />);
    const input = screen.getByLabelText('Search settings');
    fireEvent.change(input, { target: { value: 'git' } });
    fireEvent.keyDown(input, { key: 'ArrowUp' });
    fireEvent.keyDown(input, { key: 'Enter' });
    expect(onSelect).toHaveBeenCalledTimes(1);
  });

  it('Enter jumps to the top result even after the dropdown is dismissed', () => {
    const onSelect = vi.fn();
    renderWithKainBain(<SettingsSearchInput onSelect={onSelect} />);
    const input = screen.getByLabelText('Search settings');
    fireEvent.change(input, { target: { value: 'git' } });
    // Dismiss with Escape (text stays), then Enter still follows the top hit.
    fireEvent.keyDown(input, { key: 'Escape' });
    expect(screen.queryByRole('listbox')).not.toBeInTheDocument();
    fireEvent.keyDown(input, { key: 'Enter' });
    expect(onSelect).toHaveBeenCalledTimes(1);
    expect(onSelect.mock.calls[0][0]).toMatchObject({ id: 'git-repo', tab: 'files' });
  });

  it('Escape closes the dropdown without selecting', () => {
    const onSelect = vi.fn();
    renderWithKainBain(<SettingsSearchInput onSelect={onSelect} />);
    const input = screen.getByLabelText('Search settings');
    fireEvent.change(input, { target: { value: 'git' } });
    expect(screen.getByRole('listbox')).toBeInTheDocument();
    fireEvent.keyDown(input, { key: 'Escape' });
    expect(screen.queryByRole('listbox')).not.toBeInTheDocument();
    expect(onSelect).not.toHaveBeenCalled();
  });

  it('clicking a result calls onSelect with the entry', () => {
    const onSelect = vi.fn();
    renderWithKainBain(<SettingsSearchInput onSelect={onSelect} />);
    fireEvent.change(screen.getByLabelText('Search settings'), {
      target: { value: 'accent' },
    });
    fireEvent.mouseDown(screen.getByText('Accent Theme Color'));
    expect(onSelect).toHaveBeenCalledTimes(1);
    expect(onSelect.mock.calls[0][0]).toMatchObject({ id: 'accent-color', tab: 'project' });
  });
});

/***
 * MARK: System settings tabs
 * @description Single source of truth for the System Settings section tabs:
 *   id, label, and whether the settings footer's Reset control applies. The
 *   Notifications and UI panels persist immediately through their own
 *   controls (each with its own reset), so the footer Reset — which only
 *   restores the settings draft (+ Storage remount) — would be a misleading
 *   no-op there and is hidden. Every consumer (the SystemSettingsPage screen,
 *   SystemSettingsContent, unit tests, and the canary tab-bar suite) derives
 *   from this list so a new tab can never drift the expectations again.
 * @example SETTINGS_TABS.find((t) => t.id === 'ui') => { id: 'ui', label: 'UI', showFooterReset: false }
 ***/

export const SETTINGS_TABS = [
  { id: "harness", label: "Harness", showFooterReset: true },
  { id: "models", label: "Models", showFooterReset: true },
  { id: "engine", label: "Engine", showFooterReset: true },
  { id: "storage", label: "Storage", showFooterReset: true },
  { id: "notifications", label: "Notifications", showFooterReset: false },
  { id: "prompt-layout", label: "Prompt Layout", showFooterReset: false },
  { id: "ui", label: "UI", showFooterReset: false },
];

/***
 * MARK: SETTINGS_TAB_LABELS
 * @description Ordered tab labels derived from SETTINGS_TABS (render order).
 * @example SETTINGS_TAB_LABELS => ['Harness', 'Models', 'Engine', 'Storage', 'Notifications', 'UI']
 ***/
export const SETTINGS_TAB_LABELS = SETTINGS_TABS.map((tab) => tab.label);

/***
 * MARK: isFooterResetVisible
 * @description Whether the settings footer Reset applies to a section id.
 *   Unknown ids fail open (true) so a future tab without metadata keeps the
 *   legacy behaviour instead of silently losing its reset.
 * @example isFooterResetVisible('ui') => false
 * @param {string} sectionId - Active section id.
 * @returns {boolean} True when the footer Reset should render.
 ***/
export function isFooterResetVisible(sectionId) {
  if (typeof sectionId !== "string" || !sectionId) return true;
  const tab = SETTINGS_TABS.find((entry) => entry.id === sectionId);
  if (!tab) return true;
  return tab.showFooterReset !== false;
}

/***
 * MARK: accentTokens
 * @description Pure, framework-free helpers for deriving the per-project accent
 * CSS custom-property values from a hex colour. Kept DOM-free so it is trivially
 * unit-testable in isolation (no React, no jsdom layout).
 *
 * The app's Tailwind `primary`/`on-primary` tokens are defined as
 * `rgb(var(--accent) / <alpha-value>)`, so `--accent`/`--accent-on` must be
 * stored as space-separated RGB triplets (NOT hex) for opacity modifiers like
 * `bg-primary/20` to compile to valid CSS. A companion `--accent-hex` var holds
 * the raw hex for SVG/`var()` consumers (e.g. BrandMark) that cannot read a
 * triplet.
 *
 * @example accentTokens('#7bdb85') => { hex, triplet, accentOn, glow }
 ***/

export const DEFAULT_ACCENT_HEX = '#7bdb85';

/***
 * MARK: ENHANCED_CONTRAST_MINIMUM
 * @description WCAG 1.4.6 Contrast (Enhanced, AAA) minimum ratio for text.
 * Every pair emitted by accentTextPair() meets or exceeds this.
 ***/
export const ENHANCED_CONTRAST_MINIMUM = 7;

/***
 * MARK: normalizeHex
 * @description Coerces a user-supplied colour into a canonical 6-digit lowercase
 * hex string. Accepts `#rgb` and `#rrggbb` (with or without the leading `#`).
 * Any other input falls back to the default emerald so the app never receives an
 * invalid CSS colour.
 * @param {*} input
 * @returns {string} 6-digit lowercase hex, e.g. '#7bdb85'
 ***/
export function normalizeHex(input) {
  if (typeof input !== 'string') return DEFAULT_ACCENT_HEX;
  let hex = input.trim();
  if (!hex.startsWith('#')) hex = `#${hex}`;
  if (/^#[0-9a-fA-F]{3}$/.test(hex)) {
    return `#${hex[1]}${hex[1]}${hex[2]}${hex[2]}${hex[3]}${hex[3]}`.toLowerCase();
  }
  if (/^#[0-9a-fA-F]{6}$/.test(hex)) return hex.toLowerCase();
  return DEFAULT_ACCENT_HEX;
}

/***
 * MARK: hexToRgb
 * @description Parses a hex string into 0-255 RGB channels.
 * @param {string} hex
 * @returns {{r: number, g: number, b: number}}
 ***/
export function hexToRgb(hex) {
  const h = normalizeHex(hex);
  return {
    r: parseInt(h.slice(1, 3), 16),
    g: parseInt(h.slice(3, 5), 16),
    b: parseInt(h.slice(5, 7), 16),
  };
}

/***
 * MARK: relativeLuminance
 * @description WCAG 2.x relative luminance of an RGB colour (0..1).
 * @param {{r: number, g: number, b: number}} rgb
 * @returns {number}
 ***/
export function relativeLuminance({ r, g, b }) {
  const [rs, gs, bs] = [r, g, b].map((c) => {
    const s = c / 255;
    return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * rs + 0.7152 * gs + 0.0722 * bs;
}

/***
 * MARK: contrastRatio
 * @description WCAG contrast ratio between two relative luminances (1..21).
 * @param {number} l1
 * @param {number} l2
 * @returns {number}
 ***/
export function contrastRatio(l1, l2) {
  const [hi, lo] = l1 > l2 ? [l1, l2] : [l2, l1];
  return (hi + 0.05) / (lo + 0.05);
}

/***
 * MARK: mixHexTowards
 * @description Linear-RGB mix of two hex colours. `t = 0` returns `hex`,
 * `t = 1` returns `targetHex`; hue is preserved because the mix moves along
 * the straight line between the two colours (no rebrand — only a lightness
 * shift towards black or white).
 * @param {string} hex
 * @param {string} targetHex
 * @param {number} t - Mix factor in [0, 1].
 * @returns {string} Canonical 6-digit hex.
 ***/
export function mixHexTowards(hex, targetHex, t) {
  const a = hexToRgb(hex);
  const b = hexToRgb(targetHex);
  const mix = (ca, cb) => Math.round(ca + (cb - ca) * Math.min(1, Math.max(0, t)));
  const r = mix(a.r, b.r);
  const g = mix(a.g, b.g);
  const bl = mix(a.b, b.b);
  const to2 = (c) => c.toString(16).padStart(2, '0');
  return `#${to2(r)}${to2(g)}${to2(bl)}`;
}

/***
 * MARK: contrastOfPair
 * @description WCAG contrast ratio between two hex colours (1..21).
 * @param {string} fgHex
 * @param {string} bgHex
 * @returns {number}
 ***/
export function contrastOfPair(fgHex, bgHex) {
  return contrastRatio(
    relativeLuminance(hexToRgb(fgHex)),
    relativeLuminance(hexToRgb(bgHex)),
  );
}

/***
 * MARK: accentTextPair
 * @description Contrast-safe (WCAG 1.4.6, AAA ≥ 7:1) text-on-accent pair for a
 * project accent. Black or white text is preferred on the accent unchanged;
 * when neither reaches the minimum (mid-luminance accents — no foreground on
 * earth can, so the surface itself must move), the background is shifted the
 * smallest distance towards black or white that reaches it. The hue never
 * changes, only lightness, and already-conformant accents pass through
 * byte-identical.
 * @param {*} [input] - Hex colour (defaults to emerald).
 * @param {number} [minRatio] - Minimum contrast (default 7, AAA enhanced).
 * @returns {{background: string, foreground: string}} Canonical hexes with
 *   `contrastOfPair(foreground, background) >= minRatio` (guaranteed:
 *   t = 1 always yields 21:1).
 ***/
export function accentTextPair(input = DEFAULT_ACCENT_HEX, minRatio = ENHANCED_CONTRAST_MINIMUM) {
  const bg = normalizeHex(input);
  const L = relativeLuminance(hexToRgb(bg));
  const contrastWhite = contrastRatio(L, 1);
  const contrastBlack = contrastRatio(L, 0);
  if (Math.max(contrastWhite, contrastBlack) >= minRatio) {
    return { background: bg, foreground: contrastWhite >= contrastBlack ? '#ffffff' : '#000000' };
  }
  const shiftFor = (fgHex, targetHex) => {
    for (let t = 0.01; t <= 1.0001; t += 0.01) {
      const candidate = mixHexTowards(bg, targetHex, t);
      if (contrastOfPair(fgHex, candidate) >= minRatio) return { t, background: candidate };
    }
    return { t: 1, background: targetHex };
  };
  const dark = shiftFor('#ffffff', '#000000');
  const light = shiftFor('#000000', '#ffffff');
  if (dark.t < light.t) return { background: dark.background, foreground: '#ffffff' };
  if (light.t < dark.t) return { background: light.background, foreground: '#000000' };
  return contrastWhite >= contrastBlack
    ? { background: dark.background, foreground: '#ffffff' }
    : { background: light.background, foreground: '#000000' };
}

/***
 * MARK: accentTokens
 * @description Derives the CSS custom-property values for a project accent.
 * The emitted background/foreground pair always meets WCAG 1.4.6 (AAA ≥ 7:1)
 * via accentTextPair(): conformant accents (including the default emerald)
 * pass through unchanged; mid-luminance accents shift minimally in lightness
 * (hue preserved) so on-accent text stays readable at runtime.
 * @param {*} [input] - Hex colour (defaults to emerald).
 * @returns {{hex: string, triplet: string, accentOn: string, glow: string}}
 *   - hex: canonical 6-digit hex (for `--accent-hex` / SVG consumers)
 *   - triplet: `r g b` (for `--accent`)
 *   - accentOn: `r g b` of the chosen black/white text colour (for `--accent-on`)
 *   - glow: `r g b / 0.2` translucent variant (for `--accent-glow`)
 ***/
export function accentTokens(input = DEFAULT_ACCENT_HEX) {
  const { background, foreground } = accentTextPair(input);
  const { r, g, b } = hexToRgb(background);
  const on = hexToRgb(foreground);
  return {
    hex: background,
    triplet: `${r} ${g} ${b}`,
    accentOn: `${on.r} ${on.g} ${on.b}`,
    glow: `${r} ${g} ${b} / 0.2`,
  };
}

import { describe, expect, it } from 'vitest';
import { SETTINGS_SEARCH_INDEX, searchSettings, findBestMatch } from './projectSettingsSearch';

/***
 * MARK: projectSettingsSearch tests
 * @description Verifies the settings search index: label and keyword
 *   matching, ranking, empty/no-match behaviour, and best-match lookup.
 ***/
describe('searchSettings', () => {
  it('matches by label substring, case-insensitively', () => {
    const hits = searchSettings('GIT');
    expect(hits.length).toBeGreaterThan(0);
    expect(hits[0].id).toBe('git-repo');
  });

  it('matches by keyword', () => {
    const hits = searchSettings('nickname');
    expect(hits.map((hit) => hit.id)).toContain('model-aliases');
  });

  it('ranks label hits above keyword-only hits', () => {
    // 'timeout' is in the agent-timeout label but only a keyword elsewhere.
    const hits = searchSettings('timeout');
    expect(hits.length).toBeGreaterThan(1);
    expect(hits[0].label.toLowerCase()).toContain('timeout');
  });

  it('returns an empty array for blank queries and non-matches', () => {
    expect(searchSettings('')).toEqual([]);
    expect(searchSettings('   ')).toEqual([]);
    expect(searchSettings('zzz-no-such-setting')).toEqual([]);
    // Non-string input never throws — it matches nothing.
    expect(searchSettings(null)).toEqual([]);
    expect(searchSettings(undefined)).toEqual([]);
  });

  it('matches multi-word queries on every word, in any order', () => {
    expect(searchSettings('git repo')[0]?.id).toBe('git-repo');
    expect(searchSettings('repo git')[0]?.id).toBe('git-repo');
    expect(searchSettings('centralised docs')[0]?.id).toBe('centralized-docs');
    expect(searchSettings('use task branches')[0]?.id).toBe('task-branches');
  });

  it('requires every word to hit (one miss disqualifies the entry)', () => {
    // No single setting is about both git and timeouts.
    expect(searchSettings('git timeout')).toEqual([]);
    // "git repo health" nearly matches git-repo, but health lives elsewhere.
    expect(searchSettings('git repo health')).toEqual([]);
  });

  it('covers every project-related tab', () => {
    const tabs = new Set(SETTINGS_SEARCH_INDEX.map((entry) => entry.tab));
    expect(tabs).toEqual(new Set(['project', 'aliases', 'files']));
  });

  it('uses unique ids and elementIds', () => {
    const ids = SETTINGS_SEARCH_INDEX.map((entry) => entry.id);
    expect(new Set(ids).size).toBe(ids.length);
    const elementIds = SETTINGS_SEARCH_INDEX.map((entry) => entry.elementId);
    expect(new Set(elementIds).size).toBe(elementIds.length);
  });
});

describe('findBestMatch', () => {
  it('returns the single best match for jump-on-Enter', () => {
    expect(findBestMatch('git')?.id).toBe('git-repo');
    expect(findBestMatch('accent')?.id).toBe('accent-color');
  });

  it('returns null when nothing matches', () => {
    expect(findBestMatch('zzz-no-such-setting')).toBeNull();
  });
});

